import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DwhuN-9m.js";var i=JSON.parse(`{"title":"Tasks and Environment","description":"","frontmatter":{"id":"guide.tasks-and-environment","title":"Tasks and Environment","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/tasks-and-environment.md","filePath":"guides/tasks-and-environment.md"}`),a={name:`guides/tasks-and-environment.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e('<h1 id="tasks-and-environment" tabindex="-1">Tasks and Environment <a class="header-anchor" href="#tasks-and-environment" aria-label="Permalink to “Tasks and Environment”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p><code>bento run &lt;name&gt;</code> runs a task declared in the top-level <code>tasks</code> field of your project&#39;s <code>package.json</code>, after the tasks it depends on. Before Bento starts a task or a script, it loads the project&#39;s <code>.env</code> files into that launch&#39;s environment. Both features read the files your project already has; nothing needs converting to a Bento-specific format.</p><p>For a task, Bento finds the project by looking for the nearest <code>package.json</code> in the current directory or one of its parents. For a script, it starts from the script&#39;s own directory instead. The directory holding that <code>package.json</code> is the project root: tasks run there, and <code>.env</code> files and <code>node_modules/.bin</code> are read from there. If no <code>package.json</code> is found, Bento reports an error.</p><p><code>bento run &lt;target&gt;</code> treats the target as a file when it contains a path separator (<code>./server.ts</code>, <code>scripts/seed.ts</code>) or when it has a file extension and that file exists (<code>server.ts</code>). Otherwise an exact task name wins over a file of the same name. A target that is neither a task nor a file is an error; Bento never runs it as a shell command.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><h3 id="declare-tasks" tabindex="-1">Declare tasks <a class="header-anchor" href="#declare-tasks" aria-label="Permalink to “Declare tasks”">​</a></h3><table tabindex="0"><thead><tr><th>Shape</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>A string</td><td><code>&quot;lint&quot;: &quot;oxlint --fix&quot;</code></td><td>One command.</td></tr><tr><td>An array of strings</td><td><code>&quot;check&quot;: [&quot;oxfmt --check&quot;, &quot;oxlint&quot;, &quot;tsc&quot;]</code></td><td>Commands that run one after another. The first failure stops the rest.</td></tr><tr><td>An object</td><td><code>&quot;dev&quot;: { &quot;dependsOn&quot;: [&quot;db:migrate&quot;], &quot;command&quot;: &quot;bento run --watch server.ts&quot; }</code></td><td><code>dependsOn</code> lists tasks to run first; <code>command</code> is one command string. Either may be left out, but not both.</td></tr></tbody></table><p>An object with only <code>dependsOn</code> groups other tasks: it succeeds when they all succeed.</p><p>Bento checks the whole selected graph before it runs anything: the shape of every task in it, every dependency name, and cycles. It rejects empty commands, empty arrays, an object with neither a <code>command</code> nor a dependency, a <code>command</code> that is not a string, a <code>dependsOn</code> that is not a list of task names, and object fields other than <code>command</code> and <code>dependsOn</code>. Errors name the task, the missing dependency, or the cycle (<code>a → b → a</code>). Tasks outside the selected graph are not checked.</p><p><code>scripts</code> are not tasks. Bento never converts them and never runs npm-style <code>pre</code> and <code>post</code> hooks, so a <code>predev</code> script does not run before the <code>dev</code> task.</p><h3 id="run-them-in-order" tabindex="-1">Run them in order <a class="header-anchor" href="#run-them-in-order" aria-label="Permalink to “Run them in order”">​</a></h3><p>Dependencies run depth-first in the order they are declared, then the task&#39;s own command or commands. A task reached through several dependencies runs once per invocation. Tasks never run in parallel.</p><p>If a command fails, nothing after it runs: not the rest of its array, not the tasks that depend on it, and not any later task. Bento reports the task, the command, and the exit code or the signal that ended it.</p><h3 id="pass-arguments" tabindex="-1">Pass arguments <a class="header-anchor" href="#pass-arguments" aria-label="Permalink to “Pass arguments”">​</a></h3><p>Arguments after <code>--</code> are appended to the selected task&#39;s own command, shell-quoted, so spaces, quotes, <code>$</code>, and <code>;</code> arrive exactly as you typed them. Dependencies never receive them. A task with only <code>dependsOn</code> has no command to receive them, and a task with an array of commands would leave the target ambiguous, so both reject arguments.</p><h3 id="what-a-command-runs-with" tabindex="-1">What a command runs with <a class="header-anchor" href="#what-a-command-runs-with" aria-label="Permalink to “What a command runs with”">​</a></h3><p>Each command runs with <code>/bin/sh -c</code> in the project root, so inline assignments such as <code>NODE_ENV=test remix test</code>, quoting, and operators like <code>&amp;&amp;</code>, <code>||</code>, <code>;</code>, and <code>|</code> behave as they do in your shell. <code>PATH</code> starts with <code>&lt;root&gt;/node_modules/.bin</code>, then the directory of the running <code>bento</code> executable, then the inherited <code>PATH</code>, so installed package tools are found by name. Ahead of all of these, Bento adds a private directory holding only a link to itself, so <code>bento</code> in a command always means the running <code>bento</code>, even when the project installs a <code>bento</code> of its own in <code>node_modules/.bin</code>. The command receives the launch environment described below, and its stdout and stderr pass straight through.</p><p>Running a task is a trusted operation on your behalf. Its commands, and the executables they start, run with your user&#39;s full authority; Bento&#39;s grants do not sandbox them. Package tools such as <code>oxfmt</code>, <code>tsc</code>, or <code>remix db migrate</code> may run under Node.</p><h3 id="cancel-and-clean-up" tabindex="-1">Cancel and clean up <a class="header-anchor" href="#cancel-and-clean-up" aria-label="Permalink to “Cancel and clean up”">​</a></h3><p>Each command runs in its own process group. When Bento receives an interrupt (Ctrl-C) or a termination signal, it forwards that signal to the whole group, including servers started by nested commands. Processes that are still running after a 10-second grace period are killed.</p><p>A command finishes when its shell exits. If the shell leaves processes running in the background, as <code>server &amp;</code> does, Bento sends them a termination signal, kills any that remain after the same grace period, and then reports the shell&#39;s exit status. If Bento is interrupted or terminated while it waits for them, it forwards that signal to them as well and reports the task as cancelled instead; whatever remains is still killed when the original grace period ends. Either way, Bento starts the next command, or returns, only after every process in the group has exited, so no orphaned server keeps holding its port.</p><h3 id="nest-bento-commands" tabindex="-1">Nest <code>bento</code> commands <a class="header-anchor" href="#nest-bento-commands" aria-label="Permalink to “Nest bento commands”">​</a></h3><p>A task command that runs <code>bento</code> again receives two variables from the launch that started the task:</p><ul><li><code>BENTO_GRANT_CEILING</code> carries that launch&#39;s grants. The nested launch inherits them for any kind of grant it does not mention, and may narrow them; asking for a wider grant fails before any guest code runs.</li><li><code>BENTO_ENV_FILE_KEYS</code> records which variables Bento loaded from <code>.env</code> files, with a fingerprint of each loaded value. The nested launch treats those variables as file values it may load again for its own mode, rather than as values you exported. A variable the task command assigns for the nested launch is left out, so it stays explicit even when it repeats the value from <code>.env</code>: <code>DATABASE_URL=base bento run --watch server.ts</code> keeps <code>DATABASE_URL=base</code>. A variable whose value no longer matches its fingerprint is explicit too.</li></ul><p>These variables describe the trusted host&#39;s policy; they are not authority that guest code can claim.</p><p>Bento reads a command&#39;s own assignments from its text, following the shell&#39;s scoping rules:</p><ul><li><code>NAME=value</code> words before a command apply to that command alone. <code>DATABASE_URL=base true; bento run --watch server.ts</code> leaves <code>DATABASE_URL</code> to the nested launch&#39;s mode file, because the assignment never reached <code>bento</code>.</li><li>A <code>NAME=value</code> statement on its own, and the <code>NAME=value</code> arguments of <code>export</code> and <code>readonly</code>, apply to every command in the task command.</li><li>The <code>NAME=value</code> operands of <code>env</code>, after its options such as <code>-i</code>, <code>-u NAME</code>, and <code>--</code>, apply to the command <code>env</code> runs: <code>env -u UNUSED DATABASE_URL=base bento run --watch server.ts</code> keeps <code>DATABASE_URL=base</code>. An <code>env -S</code> string is split into words the way <code>env</code> splits it, so <code>env -S &#39;DATABASE_URL=base bento run --watch server.ts&#39;</code> keeps it too. When <code>env</code> runs no command, as in <code>env DATABASE_URL=base &gt; /dev/null</code>, it prints the environment and its assignments reach nothing.</li><li><code>command</code>, <code>builtin</code>, <code>exec</code>, and <code>nohup</code> run the command that follows their options with the same environment, so Bento reads that command as well: <code>nohup env DATABASE_URL=base bento run --watch server.ts</code> keeps <code>DATABASE_URL=base</code>. <code>command</code> and <code>builtin</code> run a builtin in the shell itself, so <code>command export DATABASE_URL=base</code> assigns for every later command just as <code>export</code> does. <code>exec</code>, <code>nohup</code>, and <code>env</code> start a program found on <code>PATH</code> instead, where no name is a builtin: <code>nohup export DATABASE_URL=base</code> assigns nothing, and every name there other than <code>env</code> and <code>nohup</code>, even <code>test</code> or <code>command</code>, is a program that may start <code>bento</code>, so <code>env DATABASE_URL=base command true</code> and <code>DATABASE_URL=base exec test</code> count. With <code>-v</code> or <code>-V</code>, <code>command</code> only describes the command that follows and runs nothing, so <code>command -v export DATABASE_URL=base</code> assigns nothing, and <code>DATABASE_URL=base command -v bento</code> reaches nothing.</li><li>A path to <code>env</code> or <code>nohup</code>, such as <code>/usr/bin/env</code> or <code>./bin/env</code>, counts as that utility, because each is also a program: <code>/usr/bin/env DATABASE_URL=base bento run --watch server.ts</code> keeps <code>DATABASE_URL=base</code> just as <code>env</code> does. <code>command</code> and <code>exec</code> are shell builtins, so a path such as <code>./bin/command</code> names some other program, which may start <code>bento</code> whatever its arguments: <code>DATABASE_URL=base ./bin/command true</code> counts.</li><li>A backslash that ends a line joins that line to the next before Bento reads the words, as the shell does, so a command split across lines reads as one: in <code>package.json</code>, <code>&quot;env \\\\\\n DATABASE_URL=base bento run --watch server.ts&quot;</code> keeps <code>DATABASE_URL=base</code>. The lines join inside double quotes too; inside single quotes the backslash and the newline stay as written.</li><li>Quotes are removed first, so <code>env &quot;DATABASE_URL=base&quot; …</code> and <code>export &#39;DATABASE_URL&#39;=base</code> count, while <code>echo DATABASE_URL=base</code>, a comment, and text inside quotes do not. Redirections such as <code>&gt; /dev/null</code> and <code>2&gt;&amp;1</code> are not words of the command. A here-document&#39;s body is its command&#39;s input, not command text, so a <code>DATABASE_URL=base</code> line between <code>cat &lt;&lt;EOF</code> and <code>EOF</code> does not count. The shell does run a command substitution, <code>$(…)</code> or backticks, in a body whose delimiter is unquoted, so Bento reads each line of that body as command text, and, since it does not find where a substitution ends, the text from each substitution to the body&#39;s end: a body line <code>$(DATABASE_URL=base bento run --watch server.ts)</code> keeps <code>DATABASE_URL=base</code>, even after a <code>#</code> or inside quotes, which in a body are only text, and a <code>DATABASE_URL=base</code> line in the same body counts too. A backslash before <code>$(</code> or a backtick escapes it, as in <code>\\$(date)</code>, so it runs nothing, and a body with no other substitution stays input.</li></ul><p>Bento cannot see which program a command starts, so it assumes any program may be, or may start, a nested <code>bento</code>: <code>DATABASE_URL=base remix dev</code> keeps the value explicit for a <code>bento</code> that <code>remix</code> starts. Only shell builtins that start no program, such as <code>true</code>, <code>false</code>, <code>echo</code>, <code>printf</code>, <code>test</code>, <code>cd</code>, <code>read</code>, and <code>wait</code>, are known to reach nothing, and only by their bare names where the shell finds them: a path such as <code>./test</code>, or a <code>test</code> that <code>env</code>, <code>exec</code>, or <code>nohup</code> finds on <code>PATH</code>, may be a project script in <code>node_modules/.bin</code> that starts <code>bento</code>, so <code>DATABASE_URL=base ./test</code> and <code>env DATABASE_URL=base test</code> count. A prefix assignment on a special builtin such as <code>:</code> or <code>exec</code> persists in the shell, as POSIX specifies, and counts.</p><h3 id="write-env-files" tabindex="-1">Write <code>.env</code> files <a class="header-anchor" href="#write-env-files" aria-label="Permalink to “Write .env files”">​</a></h3><ul><li>Write one <code>NAME=value</code> per line. Blank lines and lines starting with <code>#</code> are ignored, and <code>export NAME=value</code> is accepted.</li><li>Unquoted values are trimmed, and a <code>#</code> starts a comment. Quote any value that contains <code>#</code>.</li><li><code>&#39;single&#39;</code> and <code>`backtick`</code> quotes keep everything inside them literally.</li><li><code>&quot;double&quot;</code> quotes understand <code>\\n</code>, <code>\\r</code>, <code>\\t</code>, <code>\\&quot;</code>, and <code>\\\\</code>. Any other backslash stays as written.</li><li>A quoted value may span several lines.</li><li>Nothing is expanded or executed: <code>$HOME</code>, <code>${HOME}</code>, <code>$(command)</code>, and backticks stay literal text.</li><li>A malformed line stops the launch with the file and line number. The value on that line is never printed.</li></ul><h3 id="mode-and-precedence" tabindex="-1">Mode and precedence <a class="header-anchor" href="#mode-and-precedence" aria-label="Permalink to “Mode and precedence”">​</a></h3><p>Bento picks the mode once per launch:</p><ol><li>the <code>NODE_ENV</code> you set in the environment Bento started with;</li><li>otherwise the <code>NODE_ENV</code> in <code>.env</code>;</li><li>otherwise the launch default: <code>development</code> for <code>bento run --watch</code>, and no mode for anything else.</li></ol><p>Then it builds the environment from these layers, each overriding the ones above it:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Source</th></tr></thead><tbody><tr><td>1</td><td><code>.env</code></td></tr><tr><td>2</td><td><code>.env.&lt;mode&gt;</code>, only when there is a mode</td></tr><tr><td>3</td><td><code>.env.local</code></td></tr><tr><td>4</td><td>Variables you set in the environment, and inline assignments in a task command</td></tr></tbody></table><p>Missing files are skipped. A <code>NODE_ENV</code> set inside <code>.env.&lt;mode&gt;</code> or <code>.env.local</code> changes that variable but not which files load.</p><p>The effective <code>NODE_ENV</code> is part of the launch environment. A watch launch gets <code>NODE_ENV=development</code> even when the project has no <code>.env</code> files at all. The default never replaces a value that you or a file set.</p><p>Loading <code>.env</code> files never changes the environment of the process that started Bento or of a Rust host embedding it. A loaded value is not automatically visible to guest code either: a guest sees only the variables its grants allow. Task commands receive the whole prepared environment.</p><p>Bento reads <code>.env</code> files when a command starts. To pick up a change, restart the command; watch mode does not reload them.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><p>The guest book declares <code>&quot;dev&quot;: { &quot;dependsOn&quot;: [&quot;db:migrate&quot;], &quot;command&quot;: &quot;bento run --watch server.ts&quot; }</code> and <code>&quot;check:fix&quot;: { &quot;dependsOn&quot;: [&quot;fmt&quot;, &quot;lint&quot;, &quot;typecheck&quot;] }</code>, and its <code>scripts</code> also contain a <code>predev</code>.</p><p><code>bento run check:fix</code> runs <code>oxfmt</code>, then <code>oxlint --fix</code>, then <code>tsc</code>, and stops at the first failure.</p><p>Suppose the project has <code>.env</code> containing <code>DATABASE_URL=base</code> and <code>.env.development</code> containing <code>DATABASE_URL=dev</code>, and nothing is exported:</p><ol><li><code>bento run dev</code> is not a watch launch and <code>.env</code> has no <code>NODE_ENV</code>, so it has no mode. Its environment has <code>DATABASE_URL=base</code> and no <code>NODE_ENV</code>. The <code>predev</code> script does not run.</li><li><code>db:migrate</code> runs <code>remix db migrate</code> once, with <code>DATABASE_URL=base</code>.</li><li>The <code>dev</code> command <code>bento run --watch server.ts</code> inherits <code>DATABASE_URL=base</code>, and <code>BENTO_ENV_FILE_KEYS</code> marks that value as loaded from a file. As a watch launch, it selects the <code>development</code> mode, loads <code>.env</code> and then <code>.env.development</code>, and starts the server with <code>DATABASE_URL=dev</code> and <code>NODE_ENV=development</code>.</li></ol><p>Running <code>DATABASE_URL=mine bento run dev</code> instead keeps <code>DATABASE_URL=mine</code> at both levels, because a value you set always beats the files.</p><p><code>bento run test -- --reporter &quot;dot matrix&quot;</code> runs <code>NODE_ENV=test remix test --reporter &#39;dot matrix&#39;</code>, while <code>bento run check:fix -- --verbose</code> fails because <code>check:fix</code> has no command of its own.</p><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>There is no parallel task scheduling, task caching, or hot reloading of <code>.env</code> files.</li><li>Bento reads a task command&#39;s text statically, without running it, and recognizes assignments only in the forms this guide lists. Other shell constructs may not be recognized: an assignment inside <code>sh -c &#39;…&#39;</code> or <code>eval</code>, one handed to a program that runs another command, as in <code>nice env DATABASE_URL=base bento run --watch server.ts</code>, one made by <code>.</code> sourcing a file or by a script the command runs, or one made through a <code>${NAME}</code> substitution. Where the text it does recognize cannot decide, Bento keeps your value: a bare assignment or <code>export</code> counts wherever it appears in the command, even after the nested launch, and a prefix assignment on any program counts because the program might start <code>bento</code>.</li><li>That boundary rarely matters. A value that differs from the one the outer launch loaded from a file is always explicit in a nested launch, because it no longer matches its fingerprint in <code>BENTO_ENV_FILE_KEYS</code>. Only an assignment of exactly the file&#39;s value relies on Bento reading the command text: when Bento does not recognize it, the nested launch treats the value as loaded from a file and may replace it with its own mode file&#39;s value. When that case matters, write the assignment in a form this guide lists, or set the variable with <code>export</code> in the task command before the nested launch; a value that differs from the file&#39;s needs neither.</li><li>A mode is used as part of a file name, so a <code>NODE_ENV</code> containing <code>/</code> is rejected. An empty <code>NODE_ENV</code> that you set means no mode, and Bento leaves it empty.</li><li>When a signal does not stop a process, the 10-second grace period ends with a kill, which skips any further cleanup inside that process.</li></ul>',49)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};